// App.tsx
import { useState, useEffect, useRef } from 'react';
import { HashRouter as Router, Route, Routes, Navigate, useLocation } from 'react-router-dom';
import ConsolePage from './pages/ConsolePage';
import LoginPage from './pages/LoginPage';
import PrivacyPage from './pages/PrivacyPage';
import './App.scss';
import { defaultTheme, Theme } from './lib/themes';
import apiService from './lib/apiServer';
import { AuthProvider, useAuth } from './contexts/AuthContext';

function AppContent() {
  const { isAuthenticated, isLoading: authLoading, user, signOut } = useAuth();
  const [isLoading, setIsLoading] = useState(false);
  const [oaiKey, setOaiKey] = useState<string>('');
  const [theme, setTheme] = useState<Theme>(defaultTheme);
  const hasLoadedRef = useRef(false);

  // Load client data after authentication
  const loadClient = async (userEmail: string) => {
    hasLoadedRef.current = true;

    try {
      const oai_key = await apiService.getOaiKey();
      setOaiKey(oai_key || '');
      if (oai_key) {
        console.log(`get oai_key: ${oai_key.slice(0, 6)}...`);
      } else {
        console.log('ERROR: Failed to get OAI key from Supabase Edge Function');
        window.alert('Failed to get OAI key. Please try again.');
      }

      const themeJSON = await apiService.getRandomThemeImages();
      if (themeJSON) {
        setTheme(themeJSON as Theme);
        themeJSON?.topics.forEach(t => {
          (new Image()).src = t.url; // preload images
        });
        console.log('Loaded random transformed theme: ', theme);
      } else {
        console.log('ERROR: Failed to load random theme');
        window.alert('Failed to load theme data. Please try again.');
      }
    } catch (error) {
      console.error('Error loading client data:', error);
    } finally {
      setIsLoading(false);
    }
  };

  // Load client when user is authenticated
  useEffect(() => {
    if (isAuthenticated && user && !hasLoadedRef.current) {
      setIsLoading(true);
      loadClient(user.email || '');
    }
  }, [isAuthenticated, user]);

  const handleLogin = async (api_token: string) => {
    // Token is no longer needed with Supabase - auth is handled by Supabase session
    await loadClient(api_token);
  };

  const handleLogout = async () => {
    try {
      // Sign out from Supabase - this will update auth state
      await signOut();
    } catch (error) {
      console.error('Error during logout:', error);
    } finally {
      // Reset local state
      setOaiKey('');
      setTheme(defaultTheme);
      hasLoadedRef.current = false;
    }
  };

  // Show loading while auth state is being determined
  if (authLoading) {
    return <div className="loading-page">Loading...</div>;
  }

  return (
    <Routes>
      {/* Redirect / to /chat if authenticated, otherwise to /login */}
      <Route path="/" element={<NavigateTo isAuthenticated={isAuthenticated} />} />

      {/* Redirect /login to /chat if authenticated */}
      <Route path="/login" element={isAuthenticated ? <Navigate to="/chat" /> : <LoginPage onLogin={handleLogin} />} />

      {/* Add new privacy route - this doesn't require authentication */}
      <Route path="/privacy" element={<PrivacyPage />} />

      {/* Redirect /chat to /login if not authenticated and not loading */}
      <Route 
        path="/chat" 
        element={
          !isAuthenticated ? (
            <Navigate to="/login" />
          ) : isLoading ? (
            <div className="loading-page">Loading theme...</div>
          ) : (
            <div data-component="App">
              <ConsolePage 
                onLogout={handleLogout} 
                apiKey={oaiKey}
                theme={theme}
              />
            </div>
          )
        } 
      />
    </Routes>
  );
}

// Component to handle redirect for "/" route
const NavigateTo = ({ isAuthenticated }: { isAuthenticated: boolean }) => {
  const location = useLocation();

  if (location.pathname === "/" || location.pathname === "/chat") {
    return isAuthenticated ? <Navigate to="/chat" /> : <Navigate to="/login" />;
  }

  return null;
};

// Main App component with AuthProvider
function App() {
  return (
    <Router>
      <AuthProvider>
        <AppContent />
      </AuthProvider>
    </Router>
  );
}

export default App;
