import axios from 'axios';
import { supabase } from './supabaseClient';

const apiService = {
    
    getOaiKey: async (): Promise<string | undefined> => {
        try {
            const { data: { session }, error: sessionError } = await supabase.auth.getSession();
            if (sessionError || !session?.access_token) {
                console.error('Failed to get authorized session');
                return undefined;
            }
            
            const response = await supabase.functions.invoke('get_oai_key', {
                headers: {
                    Authorization: `Bearer ${session.access_token}`
                }
            });
            
            if (response.error) {
                console.error(`Failed to get OAI key. Error: ${response.error.message}`);
                return undefined;
            }
            
            return response.data.secret;
        } catch (error) {
            console.error(`Failed to get OAI key. Error: ${error}`);
            return undefined;
        }
    },
    getRandomThemeImages: async (): Promise<{ theme_id: string; topics: Array<{ id: number; topic: string; url: string }> } | undefined> => {
        try {
            const { data: { session }, error: sessionError } = await supabase.auth.getSession();
            if (sessionError || !session?.access_token) {
                console.error('Failed to get authorized session');
                return undefined;
            }
            
            const response = await supabase.functions.invoke('random_theme_images', {
                headers: {
                    Authorization: `Bearer ${session.access_token}`
                }
            });
            
            if (response.error) {
                console.error(`Failed to get theme images. Error: ${response.error.message}`);
                return undefined;
            }
            
            return response.data;
            // Example response.data:
            // {
            //     theme_id: "001",
            //     topics: [
            //         { id: 1, topic: "aa", url: "https://..." },
            //         { id: 2, topic: "bb", url: "https://..." },
            //         { id: 3, topic: "cc", url: "https://..." }
            //     ]
            // }
        } catch (error) {
            console.error(`Failed to get theme images. Error: ${error}`);
            return undefined;
        }
    },
};

export default apiService;
